import{_ as r,B as o,o as l,c as d,a8 as n,a,f as t,E as s}from"./chunks/framework.CNIpabDg.js";const b=JSON.parse('{"title":"Settings (executable)","description":"The Settings executable manages system configuration and persistent per-user appearance preferences.","frontmatter":{"layout":"doc","docType":"explanation","description":"The Settings executable manages system configuration and persistent per-user appearance preferences."},"headers":[],"relativePath":"explanation/architecture/executables/settings.md","filePath":"explanation/architecture/executables/settings.md","lastUpdated":1793145952000}'),c={name:"explanation/architecture/executables/settings.md"};function p(h,e,u,g,m,f){const i=o("CodeReference");return l(),d("div",{"data-pagefind-body":!0,"data-pagefind-meta":"date:1793145952000"},[e[15]||(e[15]=n('<h1 id="settings-executable" tabindex="-1">Settings (executable) <a class="header-anchor" href="#settings-executable" aria-label="Permalink to &quot;Settings (executable)&quot;">​</a></h1><p>The Settings executable is a tab-based graphical configuration application. It now includes <strong>Appearance</strong> alongside General, Password, Network, and About.</p><h2 id="role" tabindex="-1">Role <a class="header-anchor" href="#role" aria-label="Permalink to &quot;Role&quot;">​</a></h2><ul><li>Hosts configurable system UI tabs (general/appearance/password/network/about).</li><li>Applies a dark/light theme and five primary/secondary color presets to existing windows immediately.</li><li>Provides shortcut registration for desktop discovery.</li></ul><h2 id="startup-and-lifecycle" tabindex="-1">Startup and lifecycle <a class="header-anchor" href="#startup-and-lifecycle" aria-label="Permalink to &quot;Startup and lifecycle&quot;">​</a></h2><ol><li>Optional installation path (<code>SettingsExecutable::new</code>) ensures shortcuts directory and writes <code>/configuration/shared/shortcuts/settings.json</code>.</li><li>Runtime path constructs <code>Settings</code> window and tab view.</li><li>Event loop repeatedly dispatches window events to tab handlers until close.</li></ol><h2 id="runtime-integration-points" tabindex="-1">Runtime integration points <a class="header-anchor" href="#runtime-integration-points" aria-label="Permalink to &quot;Runtime integration points&quot;">​</a></h2><ul><li>Graphics/LVGL for tabbed UI composition.</li><li>Task module for environment and current-task context handling in specific tabs.</li><li>Authentication crate in password tab (<code>authenticate_user</code>, <code>change_user_password</code>).</li><li>Network module in network tab via interface control commands.</li><li>Graphics theme controls for live palette updates, including calls from within an existing LVGL lock.</li><li>VFS for shortcut write and network-device opening.</li></ul><h2 id="data-and-control-flow-vfs-touchpoints" tabindex="-1">Data and control flow / VFS touchpoints <a class="header-anchor" href="#data-and-control-flow-vfs-touchpoints" aria-label="Permalink to &quot;Data and control flow / VFS touchpoints&quot;">​</a></h2><ul><li>VFS write touchpoint: settings shortcut JSON file and per-user appearance record at <code>/users/&lt;uid&gt;/.appearance</code>.</li><li>Shells create private <code>/users/&lt;uid&gt;</code> home directories (mode <code>0700</code>) and set <code>HOME</code>. Appearance records are mode <code>0600</code>.</li><li>A versioned appearance record is written through a temporary replacement and restored for the user at login; native/browser startup also restore administrator preferences for the login screen.</li><li>Password tab flow: user resolution -&gt; current password validation -&gt; persisted password update through authentication crate.</li><li>Network tab flow: enumerate <code>/devices/network/*</code>, open interface file, issue control commands for status/config.</li></ul><h2 id="concurrency-and-event-loop-model" tabindex="-1">Concurrency and event-loop model <a class="header-anchor" href="#concurrency-and-event-loop-model" aria-label="Permalink to &quot;Concurrency and event-loop model&quot;">​</a></h2><ul><li><strong>Event-driven</strong> executable loop: <code>Settings::handle_events()</code> drains the owning window&#39;s events and suspends on its registered window waker. It does not sleep at a fixed 50 ms cadence.</li><li>Tab handlers perform async operations when triggered by UI events; no internal worker task fan-out in top-level loop.</li></ul><h2 id="failure-semantics" tabindex="-1">Failure semantics <a class="header-anchor" href="#failure-semantics" aria-label="Permalink to &quot;Failure semantics&quot;">​</a></h2><ul><li>UI creation/mounting failures return non-zero executable result.</li><li>Shortcut write failures surface during executable registration path.</li><li>Tab operation failures are handled per-tab (status labels/logging) or propagated as typed settings errors.</li></ul><h2 id="contract-vs-implementation" tabindex="-1">Contract vs implementation <a class="header-anchor" href="#contract-vs-implementation" aria-label="Permalink to &quot;Contract vs implementation&quot;">​</a></h2><ul><li><strong>Contract</strong>: settings executable opens configuration UI and processes tab interactions until closed.</li><li><strong>Current implementation</strong>: five fixed tabs including appearance persistence, password/network integration and shortcut registration.</li></ul><h2 id="operational-limitations" tabindex="-1">Operational limitations <a class="header-anchor" href="#operational-limitations" aria-label="Permalink to &quot;Operational limitations&quot;">​</a></h2><ul><li>Tab set is compile-time fixed.</li><li>Top-level window-event processing is waker-driven; the Wi-Fi panel additionally uses a timer to refresh connection progress even when the user sends no input. The other Network tab refresh path remains event-driven.</li></ul><h2 id="wi-fi-settings-and-native-demo" tabindex="-1">Wi-Fi settings and native demo <a class="header-anchor" href="#wi-fi-settings-and-native-demo" aria-label="Permalink to &quot;Wi-Fi settings and native demo&quot;">​</a></h2><p>Since Core #529, a Wi-Fi-capable controller exposes a Settings → Network → <code>wlan0</code> panel. It supports radio on/off, bounded scan lists, security mode/signal/channel/BSSID details, connection and disconnection, and asynchronous progress/errors. Unsupported authentication methods are shown but cannot be selected for connection. Passwords are masked, transient, and cleared after submission or dismissal; there is no stored profile or automatic reconnection policy.</p><p>For a headless native demo, run <code>mise run image:native</code> first, then:</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">mise</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run:cargo</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -p</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> xila-native-example</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --bin</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> native_example</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --no-network</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --mock-wifi</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --display-driver</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> headless</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --resolution</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> 800x600</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --disk-path</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /tmp/xila-wifi-demo.img</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --seed-image</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> target/seed/native/seed.img</span></span></code></pre></div>',22)),a("p",null,[e[0]||(e[0]=t("The mock advertises ",-1)),e[1]||(e[1]=a("code",null,"Xila demo",-1)),e[2]||(e[2]=t(" (public test password ",-1)),e[3]||(e[3]=a("code",null,"xila-demo",-1)),e[4]||(e[4]=t(") and an open ",-1)),e[5]||(e[5]=a("code",null,"Xila open",-1)),e[6]||(e[6]=t(" network. This only exercises control/UI behavior; it does not access the host wireless radio or provide Internet access. See ",-1)),s(i,{repo:"applications",path:"executables/settings/src/tabs/network/wifi.rs"}),e[7]||(e[7]=t(" and ",-1)),s(i,{repo:"platforms",path:"drivers/native/tests/wifi.rs"}),e[8]||(e[8]=t(".",-1))]),e[16]||(e[16]=n('<h2 id="appearance-and-per-user-homes" tabindex="-1">Appearance and per-user homes <a class="header-anchor" href="#appearance-and-per-user-homes" aria-label="Permalink to &quot;Appearance and per-user homes&quot;">​</a></h2><p>The Appearance tab supports light/dark mode and five primary/secondary color presets. The Zinc-based palette updates existing windows immediately, including contrasting text colors.</p><p>Each user has a private home directory at <code>/users/&lt;uid&gt;</code> (mode <code>0700</code>). Appearance preferences are stored in a small versioned record at <code>/users/&lt;uid&gt;/.appearance</code> (mode <code>0600</code>) and restored on login. The native and browser examples also restore the root user&#39;s appearance for the login screen. Changes are saved through a temporary-file replacement strategy; invalid records are rejected.</p><h2 id="tab-composition-and-event-scheduling" tabindex="-1">Tab composition and event scheduling <a class="header-anchor" href="#tab-composition-and-event-scheduling" aria-label="Permalink to &quot;Tab composition and event scheduling&quot;">​</a></h2><p><code>SettingsExecutable::new(vfs, task).await</code> installs <code>/configuration/shared/shortcuts/settings.json</code>. At launch, <code>Settings::new(context).await</code> creates an <code>OwnedWindow</code> and exactly five <code>Tab</code> variants: General, Appearance, Password, Network and About. The tab list is fixed at compile time.</p><p><code>Settings::handle_events()</code> acquires the graphics lock, dispatches an event to tabs until one handles it and then suspends on the window&#39;s registered waker. Window close/delete ends the task. There is no background worker for tab refresh.</p><h2 id="appearance-password-and-network-contracts" tabindex="-1">Appearance, password and network contracts <a class="header-anchor" href="#appearance-password-and-network-contracts" aria-label="Permalink to &quot;Appearance, password and network contracts&quot;">​</a></h2><ul><li>Appearance reads the current task&#39;s user preferences from <code>/users/&lt;uid&gt;/.appearance</code> via <code>graphics::appearance::Appearance</code>. The tab applies colors to live windows before attempting to persist the versioned record. <strong>Saving can fail after the UI change has already taken effect</strong>, in which case an error status is shown.</li><li>The password tab gets the current task identity from Task and Users, checks the current password through <code>authentication::authenticate_user</code>, then persists the replacement through <code>change_user_password</code>. The current UI requires a non-empty current password, a non-empty new password, matching confirmation and <strong>at least four characters</strong>. This is UI validation, not a strong password-policy implementation; it means a seeded user with an empty password cannot use this screen without first addressing that flow.</li><li>The Network tab enumerates <code>/devices/network</code> and issues typed controls such as <code>GET_KIND</code> (now <code>n/21</code>) and <code>IS_LINK_UP</code>. Non-Wi-Fi details retain event-driven refresh; the new Wi-Fi panel has its own scheduled status refresh while an association or scan is pending.</li></ul><p>The graphical shell provisions user homes with restrictive permissions and restores appearance after login. The executable assumes the current VFS credentials permit reading and writing the relevant files.</p><h3 id="source-and-api-references" tabindex="-1">Source and API references <a class="header-anchor" href="#source-and-api-references" aria-label="Permalink to &quot;Source and API references&quot;">​</a></h3>',10)),a("ul",null,[a("li",null,[s(i,{repo:"applications",path:"executables/settings/src/settings.rs"}),e[9]||(e[9]=t(" — event loop and tab array.",-1))]),a("li",null,[s(i,{repo:"applications",path:"executables/settings/src/tabs/appearance.rs"}),e[10]||(e[10]=t(" — immediate theme application and persistence.",-1))]),a("li",null,[s(i,{repo:"applications",path:"executables/settings/src/tabs/password.rs"}),e[11]||(e[11]=t(" — password verification and mutation.",-1))]),a("li",null,[s(i,{repo:"applications",path:"executables/settings/src/tabs/network/mod.rs"}),e[12]||(e[12]=t(" — VFS interface enumeration.",-1))]),e[13]||(e[13]=a("li",null,[a("a",{href:"/explanation/architecture/libraries/authentication.html"},"Authentication library"),t(" — password storage semantics.")],-1))]),e[17]||(e[17]=a("h2",{id:"references",tabindex:"-1"},[t("References "),a("a",{class:"header-anchor",href:"#references","aria-label":'Permalink to "References"'},"​")],-1)),a("ul",null,[a("li",null,[s(i,{repo:"applications",path:"executables/settings"})]),e[14]||(e[14]=a("li",null,[a("a",{href:"/explanation/architecture/libraries/internationalization.html"},"Internationalization")],-1))])])}const w=r(c,[["render",p]]);export{b as __pageData,w as default};
